const store = $getWorkflowStaticData('global');
store.hsCompanies = [];
store.hsCursor = null;
store.analyticsResults = [];
return [{ json: { initialized: true } }];

const store = $getWorkflowStaticData('global');
const payload = {
  filterGroups: [{ filters: [
    { propertyName: 'relationship',        operator: 'EQ',             value: 'Customer' },
    { propertyName: 'division_multiselect', operator: 'CONTAINS_TOKEN', value: "Engelman's Bakery" },
    { propertyName: 'erp_account_number',  operator: 'HAS_PROPERTY' }
  ]}],
  properties: ['hs_object_id', 'erp_account_number', 'name', 'ordering_status'],
  limit: 100
};
if (store.hsCursor) payload.after = store.hsCursor;
return [{ json: payload }];

const response = $input.first().json;
const results  = response.results || [];
const store    = $getWorkflowStaticData('global');
if (!store.hsCompanies) store.hsCompanies = [];
store.hsCompanies.push(...results);
const nextCursor = response.paging?.next?.after;
store.hsCursor   = (nextCursor && results.length > 0) ? nextCursor : null;
const hasMore    = store.hsCursor !== null ? 1 : 0;
return [{ json: { fetched: store.hsCompanies.length, thisPage: results.length, hasMore } }];

const store = $getWorkflowStaticData('global');
const companies = store.hsCompanies || [];
if (companies.length === 0) return [{ json: { skipped: true } }];
return companies.map(c => ({ json: c }));

const store = $getWorkflowStaticData('global');
const total = (store.hsCompanies || []).length;
store.hsCompanies = []; store.hsCursor = null; store.analyticsResults = [];
return [{ json: { message: 'Analytics sync complete', companiesProcessed: total } }];

const batchItems = $input.all();
const store = $getWorkflowStaticData('global');
store.currentBatch = batchItems.map(i => i.json);
const filter = batchItems
  .map(item => `customerNumber eq '${String(item.json.properties?.erp_account_number || '').replace(/'/g, "''")}'`)
  .join(' or ');
return [{ json: { invoiceFilter: filter } }];

const invData      = $input.first().json.value || [];
const store        = $getWorkflowStaticData('global');
const currentBatch = store.currentBatch || [];

const DAY = 24 * 60 * 60 * 1000;
const today = new Date();
today.setUTCHours(0, 0, 0, 0);
const todayMs = today.getTime();

// Build customer → last 10 invoices map (desc sorted from BC)
const byCustomer = {};
for (const inv of invData) {
  const cust = String(inv.customerNumber || '');
  if (!byCustomer[cust]) byCustomer[cust] = [];
  byCustomer[cust].push(inv);
}

const toUpdate = [];
for (const hsCompany of currentBatch) {
  const erpNum = String(hsCompany.properties?.erp_account_number || '').trim();
  const hsId   = hsCompany.id;
  if (!erpNum || !hsId) continue;

  const invList = (byCustomer[erpNum] || []).slice(0, 10);
  if (invList.length === 0) {
    toUpdate.push({ id: hsId, properties: { ordering_status: 'Not Ordered' } });
    continue;
  }

  // 1. Last invoice date (ms epoch at UTC midnight)
  const lastInvoiceDateMs = new Date(invList[0].postingDate + 'T00:00:00Z').getTime();

  // 2. Avg order size
  const avgOrderSize = Math.round(
    (invList.reduce((s, i) => s + (Number(i.totalAmountIncludingTax) || 0), 0) / invList.length) * 100
  ) / 100;

  // 3. Avg days between orders
  let avgDaysBetweenOrders = null;
  const sortedAsc = [...invList].sort((a, b) => new Date(a.postingDate) - new Date(b.postingDate));
  if (sortedAsc.length >= 2) {
    const gaps = [];
    for (let i = 1; i < sortedAsc.length; i++) {
      gaps.push((new Date(sortedAsc[i].postingDate) - new Date(sortedAsc[i-1].postingDate)) / DAY);
    }
    avgDaysBetweenOrders = Math.round((gaps.reduce((s, g) => s + g, 0) / gaps.length) * 10) / 10;
  }

  // 4. Risk Day and Lost Day — whole days so timestamps land at midnight UTC
  let riskDayMs, lostDayMs;
  if (avgDaysBetweenOrders !== null) {
    const riskDays = Math.max(Math.round(avgDaysBetweenOrders * 2), 5);
    const lostDays = Math.max(Math.round(avgDaysBetweenOrders * 3), 7);
    riskDayMs = lastInvoiceDateMs + riskDays * DAY;
    lostDayMs = lastInvoiceDateMs + lostDays * DAY;
  } else {
    riskDayMs = lastInvoiceDateMs + 14 * DAY;
    lostDayMs = lastInvoiceDateMs + 28 * DAY;
  }

  // 5. Ordering status
  let orderingStatus;
  if      (todayMs >= lostDayMs) orderingStatus = 'Potentially Lost';
  else if (todayMs >= riskDayMs) orderingStatus = 'Outside Ordering Pattern';
  else                            orderingStatus = 'Actively Ordering';

  // 6. Status date = when customer entered this tier
  let statusDateMs;
  if      (orderingStatus === 'Potentially Lost')         statusDateMs = lostDayMs;
  else if (orderingStatus === 'Outside Ordering Pattern') statusDateMs = riskDayMs;
  else                                                    statusDateMs = lastInvoiceDateMs;

  const props = {
    last_invoice_date:            lastInvoiceDateMs,
    avg_order_size:               avgOrderSize,
    ordering_status:              orderingStatus,
    ordering_status_date_changed: statusDateMs
  };
  if (avgDaysBetweenOrders !== null) props.avg_days_between_orders = avgDaysBetweenOrders;
  toUpdate.push({ id: hsId, properties: props });
}

return [{ json: { toUpdate, updateCount: toUpdate.length } }];
